    GameState.ball_age_ticks += 1;

    if (GameState.ball_age_ticks < 1800) {
        GameState.enemy_paddle_speed_x100 = 1500 - ((GameState.ball_age_ticks * 625) / 1800);
    } else {
        GameState.enemy_paddle_speed_x100 = 875 - (((GameState.ball_age_ticks - 1800) * 625) / 1800);
